/**
 * Hand-curated autorouting tier labels and the CI baseline skip list.
 *
 * This file is intentionally data-heavy: labels are reviewed curation, while
 * baseline skips are a snapshot of every currently uncurated catalog key.
 * Keep generation and validation deterministic; no runtime credentials or
 * discovery state belong here.
 */

import { createHash } from "node:crypto";
import { getBundledModels, getBundledProviders, type Model } from "@gajae-code/ai/core";
import {
	AUTOROUTING_SELECTOR_PATTERN,
	AUTOROUTING_TIERS,
	type AutoroutingTier,
	isValidAutoroutingSelector,
} from "./autorouting-contract";

export type TierMapKey = `${string}/${string}`;
export type TierEffort = "minimal" | "low" | "medium" | "high" | "xhigh";
export type TierAssignment = {
	tier: AutoroutingTier;
	effort?: TierEffort;
	rank: number;
};
export type TierMapSkip = { rationale: string; baseline?: true };

export type CuratedTierLabels = Record<TierMapKey, readonly TierAssignment[]>;
export type TierMapSkipList = Record<TierMapKey, TierMapSkip>;

export type AutoroutingCuratedTierMap = {
	labels: CuratedTierLabels;
	skips?: TierMapSkipList;
	skipList?: TierMapSkipList;
	version: number;
};

type NormalizedAutoroutingCuratedTierMap = {
	labels: CuratedTierLabels;
	skips: TierMapSkipList;
	version: number;
};

