/** Canonical JSON uses sorted object keys and preserves array order. */
export function canonicalJson(value: unknown): string {
	if (value === null) return "null";
	if (value === undefined) return "undefined";
	switch (typeof value) {
		case "string":
		case "boolean":
			return JSON.stringify(value);
		case "number":
			return Number.isFinite(value) ? JSON.stringify(value) : "null";
		case "bigint":
			throw new TypeError("Cannot canonicalize bigint");
		case "function":
		case "symbol":
			return "undefined";
		case "object":
			if (Array.isArray(value)) {
				return `[${value
					.map(item => {
						const encoded = canonicalJson(item);
						return encoded === "undefined" ? "null" : encoded;
					})
					.join(",")}]`;
			}
			return `{${Object.keys(value as Record<string, unknown>)
				.sort()
				.flatMap(key => {
					const encoded = canonicalJson((value as Record<string, unknown>)[key]);
					return encoded === "undefined" ? [] : [`${JSON.stringify(key)}:${encoded}`];
				})
				.join(",")}}`;
		default:
			return "undefined";
	}
}

/** UTF-8 bytes for the one-line canonical JSON representation. */
export function canonicalJsonBytes(value: unknown): Uint8Array {
	return new TextEncoder().encode(canonicalJson(value));
}

function sha256Canonical(value: unknown): string {
	return createHash("sha256").update(canonicalJsonBytes(value)).digest("hex");
}

function asCuratedMap(input: AutoroutingCuratedTierMap | CuratedTierLabels): NormalizedAutoroutingCuratedTierMap {
	if ("labels" in input && input.labels !== undefined) {
		return { labels: input.labels, skips: input.skips ?? input.skipList ?? {}, version: input.version };
	}
	return { labels: input, skips: {}, version: TIER_MAP_VERSION };
}

/** Return the fingerprint of labels, skips, and the curation map version. */
export function computeMapFingerprint(
	input: AutoroutingCuratedTierMap | CuratedTierLabels = CURATED_TIER_MAP,
	skips?: TierMapSkipList,
	version?: number,
): string {
	const map =
		skips === undefined && version === undefined
			? asCuratedMap(input)
			: {
					labels: ("labels" in input ? input.labels : input) as CuratedTierLabels,
					skips: skips ?? {},
					version: version ?? TIER_MAP_VERSION,
				};
	return sha256Canonical({ labels: map.labels, skips: map.skips, version: map.version });
}

export type TierMapValidationIssue = {
	path: string;
	message: string;
};

const KEY_PATTERN = /^[^/\s*?[\]]+\/[^\s*?[\]]+$/u;
const EFFORTS = new Set<TierEffort>(["minimal", "low", "medium", "high", "xhigh"]);
const TIER_SET = new Set<AutoroutingTier>(AUTOROUTING_TIERS);

function defaultCatalog(): readonly Model[] {
	return getBundledProviders().flatMap(provider =>
		getBundledModels(provider as Parameters<typeof getBundledModels>[0]),
	);
}

function modelKey(model: Pick<Model, "provider" | "id">): string {
	return `${model.provider}/${model.id}`;
}

function providerFromKey(key: string): string {
	return key.slice(0, key.indexOf("/"));
}

/** Collect structural and catalog-aware curation errors without throwing. */
export function collectTierMapValidationIssues(
	input: AutoroutingCuratedTierMap | CuratedTierLabels,
	catalog: readonly Model[] = defaultCatalog(),
): TierMapValidationIssue[] {
	const map = asCuratedMap(input);
	const issues: TierMapValidationIssue[] = [];
	if (!Number.isInteger(map.version) || map.version < 1) {
		issues.push({ path: "version", message: "Expected a positive integer map version." });
	}
	if (map.labels === null || typeof map.labels !== "object" || Array.isArray(map.labels)) {
		issues.push({ path: "labels", message: "Expected a labels object." });
	}
	if (map.skips === null || typeof map.skips !== "object" || Array.isArray(map.skips)) {
		issues.push({ path: "skips", message: "Expected a skips object." });
	}
	const catalogByKey = new Map(catalog.map(model => [modelKey(model), model]));
	const ranks = new Map<string, string>();
	const labelKeys = new Set<string>();
	for (const [key, assignments] of Object.entries(map.labels ?? {})) {
		labelKeys.add(key);
		if (!KEY_PATTERN.test(key) || !isValidAutoroutingSelector(key)) {
			issues.push({
				path: `labels.${key}`,
				message: `Invalid provider/model key; expected ${AUTOROUTING_SELECTOR_PATTERN}.`,
			});
			continue;
		}
		const catalogModel = catalogByKey.get(key);
		if (!catalogModel) {
			issues.push({ path: `labels.${key}`, message: "Labeled model is absent from the committed catalog." });
		}
		if (!Array.isArray(assignments)) {
			issues.push({ path: `labels.${key}`, message: "Expected an assignment array." });
			continue;
		}
		const tiers = new Set<AutoroutingTier>();
		for (let index = 0; index < assignments.length; index += 1) {
			const assignment = assignments[index] as Partial<TierAssignment> | null;
			const path = `labels.${key}.${index}`;
			if (assignment === null || typeof assignment !== "object") {
				issues.push({ path, message: "Expected an assignment object." });
				continue;
			}
			if (!TIER_SET.has(assignment.tier as AutoroutingTier)) {
				issues.push({ path: `${path}.tier`, message: "Unknown autorouting tier." });
			} else if (tiers.has(assignment.tier as AutoroutingTier)) {
				issues.push({ path, message: "A model may have at most one assignment per tier." });
			} else {
				tiers.add(assignment.tier as AutoroutingTier);
			}
			const rank = assignment.rank;
			if (typeof rank !== "number" || !Number.isInteger(rank) || rank < 1) {
				issues.push({ path: `${path}.rank`, message: "Rank must be a positive integer." });
			} else {
				const rankKey = `${providerFromKey(key)}\u0000${assignment.tier}`;
				const prior = ranks.get(`${rankKey}\u0000${rank}`);
				if (prior !== undefined && prior !== key) {
					issues.push({ path: `${path}.rank`, message: `Rank collides with ${prior} for provider/tier.` });
				} else {
					ranks.set(`${rankKey}\u0000${rank}`, key);
				}
			}
			if (assignment.effort !== undefined) {
				if (!EFFORTS.has(assignment.effort as TierEffort)) {
					issues.push({ path: `${path}.effort`, message: "Unknown tier effort." });
				} else if (catalogModel && !catalogModel.reasoning) {
					issues.push({
						path: `${path}.effort`,
						message: "Effort is only valid for reasoning-capable catalog models.",
					});
				}
			}
		}
	}
	for (const [key, skip] of Object.entries(map.skips ?? {})) {
		if (!KEY_PATTERN.test(key) || !isValidAutoroutingSelector(key)) {
			issues.push({ path: `skips.${key}`, message: "Invalid provider/model key." });
		}
		if (labelKeys.has(key))
			issues.push({ path: `skips.${key}`, message: "A key cannot be both labeled and skipped." });
		if (skip === null || typeof skip !== "object" || Array.isArray(skip)) {
			issues.push({ path: `skips.${key}`, message: "Expected a skip descriptor." });
			continue;
		}
		if (typeof skip.rationale !== "string" || skip.rationale.trim() === "") {
			issues.push({ path: `skips.${key}.rationale`, message: "Skip rationale must be a non-empty string." });
		}
		if (skip.baseline !== undefined && skip.baseline !== true) {
			issues.push({ path: `skips.${key}.baseline`, message: "Skip baseline, when present, must be true." });
		}
	}
	return issues;
}

/** Validate a curation map at module load or a caller-provided test boundary. */
export function validateTierMap(
	input: AutoroutingCuratedTierMap | CuratedTierLabels,
	catalog?: readonly Model[],
): void {
	const issues = collectTierMapValidationIssues(input, catalog);
	if (issues.length > 0) {
		throw new Error(
			`Invalid autorouting tier map:\n${issues.map(issue => `- ${issue.path}: ${issue.message}`).join("\n")}`,
		);
	}
}

export const validateCuratedTierMap = validateTierMap;
export const assertValidTierMap = validateTierMap;

validateTierMap(CURATED_TIER_MAP);
